class HallucinationDetector(Estimator):
    def __init__(self, context: Dict[str, Any]) -> None:
        super().__init__(
            context,
            stats_dependencies=[
                "sequence_logprobs",
            ],
            level="sequence",
        )

    def __call__(self, stats: Dict[str, np.ndarray]) -> np.ndarray:
        """
        Detects hallucinations based on the average uncertainty (negative log-probability) 
        of the generated tokens.

        Approach: 
        1. Compute the mean negative log-probability for each sequence.
        2. Higher mean values indicate lower average confidence, correlating with hallucinations.

        Hypothesis for future: 
        Hallucinated tokens often have significantly lower probabilities than factual tokens; 
        thus, the average negative log-probability (perplexity) of a hallucinated sequence 
        will be systematically higher than that of a factual sequence, regardless of length.
        """
        # sequence_logprobs is List[np.ndarray], inner array length = n_i - 1
        # We compute the mean of these log-probs for each sequence.
        # Higher mean = more uncertain = more likely hallucination.

        means = []
        for seq_logprobs in stats["sequence_logprobs"]:
            if len(seq_logprobs) == 0:
                means.append(0.0)
            else:
                means.append(np.mean(seq_logprobs))

        return np.array(means, dtype=np.float32)

class HallucinationDetector(Estimator):
    def __init__(self, context: Dict[str, Any]) -> None:
        super().__init__(
            context,
            stats_dependencies=[
                "sequence_logprobs",
            ],
            level="sequence",
        )

    def __call__(self, stats: Dict[str, np.ndarray]) -> np.ndarray:
        """
        Detects hallucinations by averaging log-probabilities across the sequence.

        Approach: Computes the mean of the provided sequence_logprobs for each sample.
        This normalizes the confidence score by sequence length, hypothesizing that 
        hallucinated claims exhibit lower average local confidence regardless of length,
        whereas global sums (like the baseline) are confounded by token count.

        Note: Excludes the first generated token as per input definition (logprobs shape n_i-1).
        """
        logprobs_list = stats["sequence_logprobs"]
        means = []
        for lp in logprobs_list:
            if len(lp) > 0:
                means.append(np.mean(lp))
            else:
                # Fallback if sequence is too short (only first token exists)
                means.append(0.0) 
        return np.array(means, dtype=np.float32)
